def permutations(arr, path=[]):
    if len(path) == len(arr):
        print(path)      # base case: complete permutation
        return
    for i in range(len(arr)):
        if arr[i] not in path:
            path.append(arr[i])       # choose
            permutations(arr, path)   # explore
            path.pop()                # unchoose (backtrack)

def is_safe(board, row, col, n):
    # Check same column
    for i in range(row):
        if board[i][col] == 1:
            return False
    # Check upper-left diagonal
    i, j = row-1, col-1
    while i >= 0 and j >= 0:
        if board[i][j] == 1: return False
        i -= 1; j -= 1
    # Check upper-right diagonal  
    i, j = row-1, col+1
    while i >= 0 and j < n:
        if board[i][j] == 1: return False
        i -= 1; j += 1
    return True

# BROKEN maze solver — no visited tracking
def solve_broken(maze, r, c):
    if r == EXIT_ROW and c == EXIT_COL:
        return True
    # Try all 4 directions — no visited check!
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        if solve_broken(maze, r+dr, c+dc):
            return True
    return False

# FIXED solver
def solve_fixed(maze, r, c, visited):
    if r == EXIT_ROW and c == EXIT_COL:
        return True
    visited[r][c] = True             # mark before recursing
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r+dr, c+dc
        if not visited[nr][nc]:
            if solve_fixed(maze, nr, nc, visited):
                return True
    visited[r][c] = False            # unmark on backtrack
    return False
